def create_job(
    ctx: RequestContext,
    job: RunSpec,
) -> ObjectId:
    """Create a new schematic evaluator job. An optional Idempotency-Key HTTP header (1 to 256 bytes) returns the same job for the same caller and RunSpec. Reusing a key with another RunSpec is refused.

    Arguments:
    ctx: RequestContext -- A request context object
    job: RunSpec -- The description of the job to create

    Returns:
    The ID of the newly created job
    """

    path = "/v1/api/ulv2/schematicevaluator/jobs"
    params = dict()
    headers = dict()
    body = job.to_bytes()
    res = ctx.post(path, body=body, mimetype="application/octet-stream", params=params, headers=headers)
    return ObjectId.from_bytes(res)

def get_job(
    ctx: RequestContext,
    id_: "ObjectId",
    timeout: Optional[int],
) -> Job:
    """Fetch the details of the job with the given ID. By default this will block until the job is complete.

    Arguments:
    ctx: RequestContext -- A request context object
    id_: "ObjectId" -- The ID of the job to fetch
    timeout: Optional[int] -- Timeout in milliseconds to wait before returning a response

    Returns:
    The details of the job
    """

    path = "/v1/api/ulv2/schematicevaluator/jobs/:id"
    path = path.replace(":id", str(id_), 1)

    params = dict()
    if timeout is not None:
        params["timeout"] = str(timeout)

    headers = dict()
    res = ctx.get(path, params=params, headers=headers)
    return Job.from_bytes(res)

def cancel_job(
    ctx: RequestContext,
    id_: "ObjectId",
) -> None:
    """Cancel the job with the given ID: every task of it that has not ended is ended with `cancelled`. The intent is recorded at once and carried out by the evaluator; a task that completed before the intent arrived stays complete.

    Arguments:
    ctx: RequestContext -- A request context object
    id_: "ObjectId" -- The ID of the job to cancel
    """

    path = "/v1/api/ulv2/schematicevaluator/jobs/:id"
    path = path.replace(":id", str(id_), 1)

    params = dict()
    headers = dict()
    ctx.delete(path, params=params, headers=headers)
    return

